import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  const group = new Group();

  // Create local cleanup checklist
  const cleanupTasks = [];
  const timelines = [];

  // Colors
  const rawInk = '#16161d';
  const rawPaper = '#e8ecf2';
  const rawAccent = '#ff2a38';
  const rawSurface = '#0b0b10';

  // 1. Stage / Backdrop Layer (Local gradient card base to avoid FLAT_VOID)
  const cardGeometry = new PlaneGeometry(2.4, 1.5);
  cleanupTasks.push(cardGeometry);

  // Engineered gradient material using TSL
  const cardMaterial = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.95
  });

  const uInk = vec3(0.086, 0.086, 0.114);      // #16161d
  const uSurface = vec3(0.043, 0.043, 0.063);  // #0b0b10
  const uAccent = vec3(1.0, 0.165, 0.22);      // #ff2a38

  // Base vertical gradient mixed with a subtle bottom-right accent hint
  const gradient = mix(
    uSurface,
    mix(uInk, uAccent, uv().x.mul(0.12)),
    uv().y
  );

  cardMaterial.colorNode = gradient;
  cleanupTasks.push(cardMaterial);

  const cardMesh = new Mesh(cardGeometry, cardMaterial);
  group.add(cardMesh);

  // 2. Texture Layer (imageUrl)
  const imageGeometry = new PlaneGeometry(2.3, 1.4);
  cleanupTasks.push(imageGeometry);

  const imageMaterial = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.0, // Will be animated-in once loaded
    depthWrite: false
  });
  cleanupTasks.push(imageMaterial);

  const imageMesh = new Mesh(imageGeometry, imageMaterial);
  imageMesh.position.z = 0.01;
  group.add(imageMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
      gsap.to(imageMaterial, {
        opacity: 0.85,
        duration: 0.6,
        ease: 'power2.out'
      });
    }).catch((err) => {
      console.warn('Failed to load image texture for card:', err);
    });
  }

  // 3. Typography Layer (Features 1 / Title / Identity)
  // Retrieve text content dynamically or default to spec
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textString = textItems[0]?.text ?? "FEATURES 1";

  // Display-mono micro-label style
  const textElement = ctx.fontAtlas.createText(textString.toUpperCase(), {
    fontSize: 0.13,
    color: rawPaper,
    align: 'center',
    letterSpacingPx: 3
  });

  if (textElement) {
    textElement.position.set(0, -0.4, 0.02);
    group.add(textElement);
  }

  // Subtle accent line
  const accentLineGeo = new PlaneGeometry(0.3, 0.015);
  cleanupTasks.push(accentLineGeo);
  const accentLineMat = new MeshBasicNodeMaterial({ color: rawAccent });
  cleanupTasks.push(accentLineMat);
  const accentLine = new Mesh(accentLineGeo, accentLineMat);
  accentLine.position.set(0, -0.55, 0.02);
  group.add(accentLine);

  // 4. Motion / Settle Entrance (gsap)
  group.position.set(-3.2, 1, 0.06);
  group.scale.set(0.2, 0.2, 0.2);
  group.alpha = 0;

  const tl = gsap.timeline();
  timelines.push(tl);

  tl.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out'
  });

  // Export Cleanup
  group.userData = {
    cleanup() {
      timelines.forEach((t) => t.kill());
      cleanupTasks.forEach((resource) => {
        if (resource && typeof resource.dispose === 'function') {
          resource.dispose();
        }
      });
    }
  };

  return group;
}
